{
  "ok": false,
  "name": "fillet",
  "error": {
    "type": "invalid_params",
    "message": "Additional properties are not allowed ('space' was unexpected)",
    "hint": "params must match the schema; a valid example is included",
    "valid_params_schema": {
      "type": "object",
      "properties": {
        "ids": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          },
          "minItems": 2,
          "maxItems": 2,
          "description": "the two lines to join"
        },
        "radius": {
          "type": "number",
          "minimum": 0,
          "description": "curve radius; 0 extends or trims the lines to a sharp corner"
        },
        "keep": {
          "type": "array",
          "items": {
            "type": "array",
            "items": {
              "type": "number"
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "[x, y]"
          },
          "minItems": 2,
          "maxItems": 2,
          "description": "a point on the part of each line to keep, in the order of ids (where a drafter clicks them); default: each line's end farther from where they meet"
        },
        "trim": {
          "type": "boolean",
          "description": "trim or extend the lines to the tangent points (default true); false draws only the curve"
        },
        "layer": {
          "type": "string",
          "minLength": 1,
          "description": "layer of the curve; default the first line's"
        },
        "color": {
          "type": "string",
          "description": "named CAD color (black, red, yellow, green, cyan, blue, magenta, gray, white) or '#RRGGBB'"
        },
        "linetype": {
          "type": "string",
          "enum": [
            "continuous",
            "dashed",
            "center",
            "hidden",
            "dot",
            "phantom"
          ]
        }
      },
      "required": [
        "ids",
        "radius"
      ],
      "additionalProperties": false
    },
    "example": {
      "ids": [
        "LN-001",
        "LN-002"
      ],
      "radius": 50.0
    }
  },
  "warnings": []
}
